// The app sends the whole last day each time, so only the newest is kept.
const body = $input.first().json.body || {};
if (!body.as_of || !Array.isArray(body.accounts) || !body.accounts.every((a) => Array.isArray(a && a.lines))) {
  throw new Error('Not a trail: as_of, and accounts each with lines, are required');
}
$getWorkflowStaticData('global').trail = {
  as_of: body.as_of,
  // This side's clock: the box watch judges silence by it, never by the box's own.
  received_at: new Date().toISOString(),
  accounts: body.accounts,
  unreadable: Array.isArray(body.unreadable) ? body.unreadable : [],
  // The box's probes, { '<probe>': { state: 'held'|'broken', since, fix } }; absent from an older box.
  health: body.health && typeof body.health === 'object' && !Array.isArray(body.health) ? body.health : {},
};
return [{ json: { ok: true } }];

// Briefing plugin: the APP section. Who signed in, and what each account did,
// as the app last told it.
// Contract: 05_daily-briefing/docs/briefing-plugin-spec.md
//
// PLAIN TEXT ONLY, never HTML. The briefing escapes centrally.
const MAX_ACCOUNTS = 8;
const STALE_AFTER_H = 2;   // the app tells every half hour

const tz = $('When Called for Briefing').first().json.tz || 'UTC';
const told = $getWorkflowStaticData('global').trail;
const section = (blocks, empty, summary = '') => [{ json: { key: 'app', icon: '🧪', title: 'APP · last 24h', summary, blocks, empty } }];
// Always exactly one item: zero items is indistinguishable from a crash.
if (!told) return section([], 'The app has not told anything yet');

const clock = (ms, withDay) => new Date(ms).toLocaleString('en-GB', {
  ...(withDay ? { day: '2-digit', month: 'short' } : {}),
  hour: '2-digit', minute: '2-digit', hour12: false, timeZone: tz,
});
const time = (at) => (Number.isFinite(Date.parse(at)) ? clock(Date.parse(at)) : '?');
// The app's own words, spaced: 'start-run' reads 'start run', 'terms_accepted' 'terms accepted'.
const words = (what) => String(what || '?').replace(/[-_]/g, ' ');
// Repeats in a row are one entry: 'start run ×2'.
const runs = (list) => list.reduce((out, w) => {
  const last = out.at(-1);
  if (last && last.w === w) last.k += 1; else out.push({ w, k: 1 });
  return out;
}, []).map(({ w, k }) => w + (k > 1 ? ' ×' + k : ''));

// Sign-in and the account's creation are said in the heading; everything else is what was done.
const SAID_ABOVE = new Set(['signed_in', 'account_created']);
// The device a line was done from, as the box classed it; absent from an older box.
const device = (l) => (/^(phone|tablet|computer)$/.test(String((l && l.device) || '')) ? ' (' + l.device + ')' : '');
// Free text from the box is clipped: one long line must not push the briefing past its limit.
const TEXT_MAX = 80;
const LINE_MAX = 240;
const clip = (v, n) => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n - 1) + '…' : s;
};
const who = (a) => String(a.who || '?').split('@')[0];
// A refused request is one line per request, and a deploy makes dozens. They are grouped:
// '500 on /api/v1/machine-status ×18, /api/v1/auth/quota-status ×6 (13:44–15:20)'.
// The subject reads '<METHOD> <path> -> <status> <code> [<request id>]: <message>'; the
// request id is never printed. A 5xx is the app's fault, not the user's: it is an alert.
const REFUSED = /^\s*[A-Z]+\s+(\S+)\s+->\s+(\d{3})\b/;
const grouped = (lines) => {
  const byStatus = new Map();
  for (const l of lines) {
    const m = REFUSED.exec(String(l.subject || ''));
    const status = m ? m[2] : '?';
    const path = m ? clip(m[1].split('?')[0], 48) : clip(l.subject || 'an unreadable request', 48);
    if (!byStatus.has(status)) byStatus.set(status, new Map());
    const paths = byStatus.get(status);
    paths.set(path, (paths.get(path) || 0) + 1);
  }
  const at = lines.map((l) => Date.parse(l.at)).filter(Number.isFinite).sort((x, y) => x - y);
  const span = at.length ? ' (' + clock(at[0]) + (clock(at.at(-1)) !== clock(at[0]) ? '–' + clock(at.at(-1)) : '') + ')' : '';
  const text = [...byStatus].map(([status, paths]) => status + ' on '
    + [...paths].sort((x, y) => y[1] - x[1]).slice(0, 4).map(([p, k]) => p + (k > 1 ? ' ×' + k : '')).join(', ')
    + (paths.size > 4 ? ', +' + (paths.size - 4) + ' more' : '')).join('; ');
  return { n: lines.length, text: text + span };
};
const refusals = (a) => {
  const all = a.lines.filter((l) => l.what === 'request_refused');
  const isFault = (l) => /^5/.test((REFUSED.exec(String(l.subject || '')) || [])[2] || '');
  return { faults: grouped(all.filter(isFault)), refused: grouped(all.filter((l) => !isFault(l))) };
};

const blocks = [];
const age =Date.now() - Date.parse(told.as_of);
if (!(age < STALE_AFTER_H * 3600e3)) {
  blocks.push({ heading: 'Stale', items: ['Last told ' + (Number.isFinite(age) ? clock(Date.now() - age, true) : 'at an unreadable time')] });
}

const accounts = told.accounts.filter((a) => a && Array.isArray(a.lines) && a.lines.length);
const signedIn = accounts.filter((a) => a.lines.some((l) => l.what === 'signed_in'));
const opened = accounts.filter((a) => a.lines.some((l) => l.what === 'account_created'));
if (accounts.length) {
  blocks.push({ items: [accounts.length + ' active · ' + signedIn.length + ' signed in · ' + opened.length + ' new'] });
}
for (const a of accounts.slice(0, MAX_ACCOUNTS)) {
  const ins = a.lines.filter((l) => l.what === 'signed_in');
  const heading = [
    String(a.who || '?'),
    opened.includes(a) ? 'new' + (ins.length ? '' : device(a.lines.find((l) => l.what === 'account_created'))) : '',
    ins.length ? 'signed in ' + ins.map((l) => time(l.at) + (l.subject ? ' ' + l.subject : '') + device(l)).join(', ') : 'no sign-in, session still open',
  ].filter(Boolean).join(' · ');
  // One line per dataset, in the order first touched; account-level acts beside them.
  const byPlace = new Map();
  for (const l of a.lines.filter((x) => !SAID_ABOVE.has(x.what) && x.what !== 'request_refused')) {
    const place = l.dataset || (l.campaign ? 'a deleted campaign' : '');
    const what = clip(words(l.what) + (!place && l.subject ? ' ' + l.subject : ''), TEXT_MAX) + (l.by ? ' (by ' + l.by + ')' : '');
    if (!byPlace.has(place)) byPlace.set(place, []);
    byPlace.get(place).push(what);
  }
  const items = [...byPlace].map(([place, did]) => clip((place ? place + ': ' : '') + runs(did).join(', '), LINE_MAX));
  const { faults, refused } = refusals(a);
  if (faults.n) items.push(faults.n + ' requests failed on a server error (see attention)');
  if (refused.n) items.push('refused ' + refused.text);
  blocks.push({ heading, items: items.length ? items : ['nothing else'] });
}
if (accounts.length > MAX_ACCOUNTS) {
  blocks.push({ heading: 'More', items: accounts.slice(MAX_ACCOUNTS).map((a) => String(a.who || '?') + ' · ' + a.lines.length + ' lines') });
}
// Unreadable accounts are an alert: plain words, the account by its email. An entry is
// { workspace, email, reason, self } from the box, or a bare workspace id from an older
// box, which is then the only name there is.
const unreadable = told.unreadable.map((u) => (u && typeof u === 'object' ? u : { workspace: String(u) }));
if (unreadable.length) {
  const name = (u) => (u.self ? 'you' : u.email ? String(u.email).split('@')[0] : String(u.workspace || '?'));
  const reasons = [...new Set(unreadable.map((u) => clip(u.reason, TEXT_MAX)).filter(Boolean))];
  blocks.push({
    level: 'alert',
    items: ['App: activity of ' + unreadable.length + (unreadable.length === 1 ? ' account' : ' accounts') + ' unreadable\n'
      + unreadable.map(name).join(', ') + '\n'
      + (reasons.length ? reasons.join('; ') : 'the app sent no reason; check its trail on the box')],
  });
  if (!accounts.length) blocks.push({ items: ['no activity readable (see attention)'] });
}
// A run that stopped before it finished is an alert. The box sends run_stopped only for
// an abnormal stop, with subject '<campaign>/<cycle>: <stop reason>'. It is read over
// every account, not only the eight printed below.
const stops = accounts.flatMap((a) => a.lines.filter((l) => l.what === 'run_stopped').map((l) => {
  const subject = String(l.subject || '');
  const cut = subject.indexOf(': ');
  const reason = cut >= 0 ? subject.slice(cut + 2).trim() : '';
  const place = l.dataset || (l.campaign ? 'a deleted campaign' : 'no dataset');
  return who(a) + "'s run stopped: " + clip(reason || 'the app sent no reason', TEXT_MAX) + ' (' + place + ')';
}));
if (stops.length) blocks.push({ level: 'alert', items: stops });
// A server error is an app fault: an alert for every account, not only the eight shown.
const faults = accounts.map((a) => ({ a, f: refusals(a).faults })).filter(({ f }) => f.n).map(({ a, f }) =>
  'App: ' + f.n + (f.n === 1 ? ' request' : ' requests') + ' of ' + (a.self ? 'yours' : who(a)) + ' failed on a server error\n'
  + f.text + '\nan app fault, not the user\'s; check the box logs for that time');
// The box's probes: health = { '<probe>': { state: 'held'|'broken', since: iso|null, fix } }.
// Every broken probe is an alert, in the box's own words; held, absent or empty prints nothing.
// No probe is special here: the box names it and says the fix.
const since = (iso) => {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return '';
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', day: '2-digit', month: '2-digit', hour12: false, timeZone: tz })
    .formatToParts(new Date(t)).map((x) => [x.type, x.value]));
  return ' since ' + p.hour + ':' + p.minute + ', ' + p.day + '.' + p.month;
};
const health = told.health && typeof told.health === 'object' ? Object.entries(told.health) : [];
const broken = health.filter(([, h]) => h && h.state === 'broken').map(([probe, h]) =>
  clip(probe, 48) + ' broken' + since(h.since) + (h.fix ? ' — ' + clip(h.fix, 160) : ''));
if (broken.length) blocks.push({ level: 'alert', items: broken });
if (faults.length) blocks.push({ level: 'alert', items: faults });

const summary = accounts.length ? accounts.length + ' active in the app' : '';
return section(blocks, 'Nobody signed in or did anything', summary);

// The box watch: one Telegram line when the box itself goes down, one when it is back, never a repeat.
// Only what the box cannot report about itself, each judged from outside it:
//   the app's sends stop arriving   -> the box, its admin bot or its network is down
//   the public health URL fails     -> the app or its tunnel is down
// A broken probe in the trail's `health` is NOT sent from here: the box's admin bot already
// Telegrams every health change once, and the briefing lists what is still broken.
const QUIET_AFTER_MIN = 75;   // the app sends every 30 minutes; two missed sends and a margin
const APP_HEALTH_URL = 'https://app.promptpotter.com/api/v1/health';
const tz = 'Europe/Zurich';

const memory = $getWorkflowStaticData('global');
const said = memory.watch || { quiet: false, app: '' };
const told = memory.trail;
const clock = (ms) => new Date(ms).toLocaleString('en-GB', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', hour12: false, timeZone: tz });

const heard = told ? Date.parse(told.received_at || told.as_of) : NaN;
const quiet = !(Date.now() - heard < QUIET_AFTER_MIN * 60e3);

let app = '';
try {
  const r = await this.helpers.httpRequest({ url: APP_HEALTH_URL, timeout: 15000, returnFullResponse: true, ignoreHttpStatusErrors: true });
  if (r.statusCode !== 200) app = 'HTTP ' + r.statusCode;
} catch (e) {
  app = String(e.message || e).slice(0, 120);
}

const lines = [];
if (quiet && !said.quiet) lines.push('🔴 Box quiet · no word from the app since ' + (Number.isFinite(heard) ? clock(heard) : 'ever') + ': the box, its admin bot or its network is down');
if (!quiet && said.quiet) lines.push('🟢 Box back · the app is talking again');
if (app && !said.app) lines.push('🔴 App unreachable from outside · ' + app);
if (!app && said.app) lines.push('🟢 App reachable again');

memory.watch = { quiet, app };
return lines.length ? [{ json: { text: lines.join('\n') } }] : [];
